/**
 * EIP-712 vector consistency test: the typed data the SDK builds must reproduce
 * the digest and signature of every (already executed and verified against the real contract) vector in
 * sdk/test-vectors/eip712-vectors.json. The vectors are generated by `forge test --match-contract SDKVectorsTest`.
 */
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { privateKeyToAccount } from 'viem/accounts';
import { toFunctionSelector } from 'viem';

import {
  buildBurnAuthorizationTypedData,
  buildPermitTypedData,
  buildReceiveAuthorizationTypedData,
  buildTransferAuthorizationTypedData,
  typedDataDigest,
} from '../src/typedData.js';
import type { Address, Bytes32, Eip712Domain, Hex, UnsignedTypedData } from '../src/types.js';

interface VectorFile {
  domain: Eip712Domain & { domainSeparator: Bytes32 };
  signers: { authorizer: { address: Address; privateKey: Hex } };
  vectors: Record<
    string,
    {
      primaryType: string;
      submitFunction: string;
      message: Record<string, string>;
      structHash: Bytes32;
      digest: Bytes32;
      signature: { v: number; r: Bytes32; s: Bytes32; packed: Hex };
      verifiedOnChain: boolean;
    }
  >;
}

const file: VectorFile = JSON.parse(
  readFileSync(new URL('../../../test-vectors/eip712-vectors.json', import.meta.url), 'utf8'),
);

const domain: Eip712Domain = {
  name: file.domain.name,
  version: file.domain.version,
  chainId: file.domain.chainId,
  verifyingContract: file.domain.verifyingContract,
};

const authorizer = privateKeyToAccount(file.signers.authorizer.privateKey);

function buildFromVector(vec: VectorFile['vectors'][string]): UnsignedTypedData {
  const m = vec.message;
  switch (vec.primaryType) {
    case 'TransferWithAuthorization':
      return buildTransferAuthorizationTypedData(domain, {
        from: m.from as Address,
        to: m.to as Address,
        value: BigInt(m.value),
        validAfter: BigInt(m.validAfter),
        validBefore: BigInt(m.validBefore),
        nonce: m.nonce as Bytes32,
      });
    case 'ReceiveWithAuthorization':
      return buildReceiveAuthorizationTypedData(domain, {
        from: m.from as Address,
        to: m.to as Address,
        value: BigInt(m.value),
        validAfter: BigInt(m.validAfter),
        validBefore: BigInt(m.validBefore),
        nonce: m.nonce as Bytes32,
      });
    case 'BurnFromWithAuthorization':
      return buildBurnAuthorizationTypedData(domain, {
        from: m.from as Address,
        value: BigInt(m.value),
        validAfter: BigInt(m.validAfter),
        validBefore: BigInt(m.validBefore),
        nonce: m.nonce as Bytes32,
      });
    case 'Permit':
      return buildPermitTypedData(domain, {
        owner: m.owner as Address,
        spender: m.spender as Address,
        value: BigInt(m.value),
        nonce: BigInt(m.nonce),
        deadline: BigInt(m.deadline),
      });
    default:
      throw new Error(`unknown primaryType ${vec.primaryType}`);
  }
}

describe('EIP-712 vectors (verified on-chain by forge)', () => {
  it('has vectors to test', () => {
    expect(Object.keys(file.vectors).length).toBeGreaterThanOrEqual(6);
  });

  for (const [key, vec] of Object.entries(file.vectors)) {
    describe(key, () => {
      it('is marked as verified on-chain', () => {
        expect(vec.verifiedOnChain).toBe(true);
      });

      it('reproduces the digest', () => {
        expect(typedDataDigest(buildFromVector(vec))).toBe(vec.digest);
      });

      it('reproduces the packed signature with the authorizer key', async () => {
        const typed = buildFromVector(vec);
        const signature = await authorizer.signTypedData({
          domain: typed.domain,
          types: typed.types,
          primaryType: typed.primaryType,
          message: typed.message,
        });
        expect(signature).toBe(vec.signature.packed);
      });

      it('submitFunction selector is valid', () => {
        // The vector's declared submit-function signature must produce a valid selector (guards against typos in the JSON).
        expect(toFunctionSelector(`function ${vec.submitFunction}`)).toMatch(/^0x[0-9a-f]{8}$/);
      });
    });
  }
});
